-- Slice 2.5 platform pieces (ADR-0010 deferral triggers: the first personal-data field and the
-- first public unauthenticated write): per-subject keys (ADR-0003, ADR-0007), rate-limit
-- windows and spent proof-of-work challenges. Generated by prisma migrate diff, then the
-- hand-written CHECKs, grants and row-level security at the end.
-- CreateTable
CREATE TABLE "platform"."subject_key" (
    "tenant_id" VARCHAR(32) NOT NULL,
    "subject_id" UUID NOT NULL,
    "module" VARCHAR(32) NOT NULL,
    "wrapped_key" BYTEA,
    "created_at" TIMESTAMPTZ(3) NOT NULL,
    "destroyed_at" TIMESTAMPTZ(3),

    CONSTRAINT "subject_key_pkey" PRIMARY KEY ("tenant_id","subject_id")
);

-- CreateTable
CREATE TABLE "platform"."rate_limit_window" (
    "tenant_id" VARCHAR(32) NOT NULL,
    "bucket" VARCHAR(64) NOT NULL,
    "window_start" TIMESTAMPTZ(3) NOT NULL,
    "hits" INTEGER NOT NULL,

    CONSTRAINT "rate_limit_window_pkey" PRIMARY KEY ("tenant_id","bucket","window_start")
);

-- CreateTable
CREATE TABLE "platform"."captcha_spent" (
    "tenant_id" VARCHAR(32) NOT NULL,
    "challenge_hash" VARCHAR(64) NOT NULL,
    "expires_at" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "captcha_spent_pkey" PRIMARY KEY ("tenant_id","challenge_hash")
);

-- CreateIndex
CREATE INDEX "rate_limit_window_tenant_id_window_start_idx" ON "platform"."rate_limit_window"("tenant_id", "window_start");

-- CreateIndex
CREATE INDEX "captcha_spent_tenant_id_expires_at_idx" ON "platform"."captcha_spent"("tenant_id", "expires_at");


-- Hand-written: integrity backstops Prisma cannot express. The tenant pattern repeats the
-- kernel's single rule (parseTenantId).
ALTER TABLE "platform"."subject_key"
  ADD CONSTRAINT "subject_key_tenant_id_check" CHECK ("tenant_id" ~ '^[a-z][a-z0-9-]{1,31}$'),
  ADD CONSTRAINT "subject_key_module_check" CHECK ("module" ~ '^[a-z][a-z0-9-]{0,31}$'),
  -- A live key has its wrapped bytes (version 1 + IV 12 + tag 16 + key 32); a destroyed key
  -- has none, and a key never comes back.
  ADD CONSTRAINT "subject_key_state_check" CHECK (
    ("destroyed_at" IS NULL AND "wrapped_key" IS NOT NULL AND octet_length("wrapped_key") = 61)
    OR ("destroyed_at" IS NOT NULL AND "wrapped_key" IS NULL)
  );

ALTER TABLE "platform"."rate_limit_window"
  ADD CONSTRAINT "rate_limit_window_tenant_id_check" CHECK ("tenant_id" ~ '^[a-z][a-z0-9-]{1,31}$'),
  ADD CONSTRAINT "rate_limit_window_bucket_check" CHECK ("bucket" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT "rate_limit_window_hits_check" CHECK ("hits" >= 1);

ALTER TABLE "platform"."captcha_spent"
  ADD CONSTRAINT "captcha_spent_tenant_id_check" CHECK ("tenant_id" ~ '^[a-z][a-z0-9-]{1,31}$'),
  ADD CONSTRAINT "captcha_spent_challenge_hash_check" CHECK ("challenge_hash" ~ '^[0-9a-f]{64}$');

-- Hand-written: a destroyed subject key stays destroyed, for every role, the owner included
-- (erasure is final; security review of slice 2.5, L2).
CREATE FUNCTION "platform"."subject_key_reject_revival"() RETURNS trigger
  LANGUAGE plpgsql
AS $$
BEGIN
  IF OLD."destroyed_at" IS NOT NULL THEN
    RAISE EXCEPTION 'platform.subject_key: a destroyed key cannot change'
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "subject_key_stays_destroyed"
  BEFORE UPDATE ON "platform"."subject_key"
  FOR EACH ROW EXECUTE FUNCTION "platform"."subject_key_reject_revival"();

-- Grants. A subject key is inserted once and then only destroyed: UPDATE of the two columns
-- that destroying sets, and the CHECK above refuses any other change of state. Rate-limit
-- windows and spent challenges are counters, pruned by the platform job.
GRANT SELECT, INSERT, UPDATE ("wrapped_key", "destroyed_at") ON TABLE "platform"."subject_key" TO "phoenix_app";
GRANT SELECT, INSERT, UPDATE ("hits"), DELETE ON TABLE "platform"."rate_limit_window" TO "phoenix_app";
GRANT SELECT, INSERT, DELETE ON TABLE "platform"."captcha_spent" TO "phoenix_app";

-- Row-level security (ADR-0002), enabled and forced, with the reference policy of
-- platform.isolation_probe on every table.
ALTER TABLE "platform"."subject_key" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "platform"."subject_key" FORCE ROW LEVEL SECURITY;
CREATE POLICY "subject_key_tenant_isolation" ON "platform"."subject_key"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());

ALTER TABLE "platform"."rate_limit_window" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "platform"."rate_limit_window" FORCE ROW LEVEL SECURITY;
CREATE POLICY "rate_limit_window_tenant_isolation" ON "platform"."rate_limit_window"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());

ALTER TABLE "platform"."captcha_spent" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "platform"."captcha_spent" FORCE ROW LEVEL SECURITY;
CREATE POLICY "captcha_spent_tenant_isolation" ON "platform"."captcha_spent"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());
